const tituloRelatorio: string = "Relatório mensal";
const paginasRelatorio: number = 12;
const relatorioPublicado: boolean = false;
const idRelatorio: symbol = Symbol("relatorio");
const bytesDoRelatorio: bigint = 12000000000n;
const revisorRelatorio: string | null = null;

function imprimirResumo(nomeDoDocumento: string, total: number): void {
  console.log(`${nomeDoDocumento} tem ${total} páginas`);
}

imprimirResumo(tituloRelatorio, paginasRelatorio);
// Relatório mensal tem 12 páginas
console.log(relatorioPublicado, revisorRelatorio); // false null
console.log(typeof idRelatorio, bytesDoRelatorio > 0n); // symbol true

function descreverValor(valor: unknown): string {
  if (typeof valor === "string") {
    return `string com ${valor.length} caracteres`;
  }
  if (typeof valor === "number") {
    return `número ${valor.toFixed(2)}`;
  }
  if (typeof valor === "boolean") {
    return valor ? "booleano verdadeiro" : "booleano falso";
  }
  if (valor === null) {
    return "o valor null";
  }
  if (valor === undefined) {
    return "o valor undefined";
  }
  if (Array.isArray(valor)) {
    return `array com ${valor.length} elementos`;
  }
  return "outro tipo qualquer";
}

console.log(descreverValor("Ana")); // string com 3 caracteres
console.log(descreverValor(3.5)); // número 3.50
console.log(descreverValor(true)); // booleano verdadeiro
console.log(descreverValor(null)); // o valor null
console.log(descreverValor([1, 2, 3])); // array com 3 elementos

type EstadoEncomenda = "pendente" | "pago" | "cancelado";

function mensagemDoEstado(estado: EstadoEncomenda): string {
  switch (estado) {
    case "pendente":
      return "A aguardar pagamento";
    case "pago":
      return "Pagamento confirmado";
    case "cancelado":
      return "Encomenda cancelada";
    default: {
      const naoTratado: never = estado;
      throw new Error(`Estado desconhecido: ${String(naoTratado)}`);
    }
  }
}

console.log(mensagemDoEstado("pendente")); // A aguardar pagamento
console.log(mensagemDoEstado("pago")); // Pagamento confirmado
console.log(mensagemDoEstado("cancelado")); // Encomenda cancelada

interface UtilizadorValidado {
  nome: string;
  idade: number;
}

function campoInvalido(campo: string): never {
  throw new Error(`Campo inválido: ${campo}`);
}

function lerUtilizador(dados: unknown): UtilizadorValidado {
  if (typeof dados !== "object" || dados === null) {
    campoInvalido("raiz");
  }
  const registo = dados as Record<string, unknown>;
  const nomeLido = registo["nome"];
  const idadeLida = registo["idade"];
  if (typeof nomeLido !== "string" || nomeLido.length === 0) {
    campoInvalido("nome");
  }
  if (typeof idadeLida !== "number" || Number.isNaN(idadeLida)) {
    campoInvalido("idade");
  }
  return { nome: nomeLido, idade: idadeLida };
}

const brutoDoJson: unknown = JSON.parse('{"nome":"Ana","idade":34}');
const utilizadorValido = lerUtilizador(brutoDoJson);
console.log(utilizadorValido.nome, utilizadorValido.idade); // Ana 34

try {
  lerUtilizador({ nome: "Bruno" });
} catch (erro) {
  console.log((erro as Error).message); // Campo inválido: idade
}
